// Gate update: a six-state machine that opens, holds and closes the gate and drives its travel and the level-15 flags.
void vertical_gate_update(GateMoby *m) {
    GateVars *d = m->vars;
    float step;

    switch (m->state) {
        case 0:
            d->home = m->pos;
            m->state = 1;
            d->locked = 0;
            if (d->key != -1) {
                m->f30 = 0xFF;
            }
            if (gemlik_available_r[3] != 0 && d->key != -1) {
                m->pos.z = m->pos.z - D_L15_00161578_2A48B0;
                m->state = 5;
            }
            break;
        case 1:
            d->travel = 0;
            if (d->key != -1) {
                l15_key_gate_open_lui = 0;
            }
            if (d->trigger != -1) {
                OtherMoby *p = (OtherMoby *)((char *)D_L15_00160058_2A48B0 + (d->trigger << 8));
                if (p == 0 || p->state == 0xFE || p->state == 0xFD) {
                    if (quartu_alarm_on_r == 0) {
                        m->state = 2;
                        d->locked = 1;
                    }
                }
            } else {
                if (is_point_inside_clip_volume(&((struct Hero *)((char *)&hero_globals_base_r + 0xE1D))->motion.pos,
                                                d->vol_near)) {
                    if (d->key == -1 || (hero_globals_base_r + 0xE9D)[0x2024] == 2) {
                        m->state = 2;
                    }
                }
            }
            if (gemlik_available_r[3] != 0 && d->key != -1) {
                m->pos.z = d->home.z - D_L15_00161578_2A48B0;
                m->state = 5;
            }
            break;
        case 2:
            step = (D_L15_00161578_2A48B0 / 0.6f) * g_frame_time_r;
            if (d->key != -1) {
                step = step * 5.0f;
            }
            if (((SoundSlot *)(hero_globals_base_r + 0x1D + d->sound * 0x70))->owner != m ||
                ((SoundSlot *)(hero_globals_base_r + 0x1D + d->sound * 0x70))->active == 0) {
                d->sound = Moby_PlaySound_r(0, 4, m);
            }
            if (D_L15_00161578_2A48B0 < (d->travel = d->travel + step)) {
                if (d->sound != -1 && ((SoundSlot *)(hero_globals_base_r + 0x1D + d->sound * 0x70))->owner == m &&
                    ((SoundSlot *)(hero_globals_base_r + 0x1D + d->sound * 0x70))->active != 0) {
                    Sound_StopSlot(d->sound);
                }
                d->sound = -1;
                d->travel = D_L15_00161578_2A48B0;
                m->state = 3;
            }
            {
                float t = d->travel;
                float h = d->home.z;
                float z;
                if (d->key != -1) {
                    t = -t;
                    z = h + t;
                } else {
                    z = h + t;
                }
                m->pos.z = z;
            }
            break;
        case 3:
            if (d->key != -1) {
                l15_key_gate_open_lui = 1;
            }
            if (is_point_inside_clip_volume(&((struct Hero *)((char *)&hero_globals_base_r + 0xE1D))->motion.pos,
                                            d->vol_trigger) != 0 ||
                is_point_inside_clip_volume(quartu_camera_pos_r, d->vol_trigger) != 0) {
                if (is_point_inside_clip_volume(&((struct Hero *)((char *)&hero_globals_base_r + 0xE1D))->motion.pos,
                                                d->key) == 0) {
                    break;
                }
            }
            if (d->locked == 0) {
                m->state = 4;
            }
            break;
        case 4:
            step = (D_L15_00161578_2A48B0 / 0.6f) * g_frame_time_r;
            if (d->key != -1) {
                step = step * 5.0f;
            }
            if (((SoundSlot *)(hero_globals_base_r + 0x1D + d->sound * 0x70))->owner != m ||
                ((SoundSlot *)(hero_globals_base_r + 0x1D + d->sound * 0x70))->active == 0) {
                d->sound = Moby_PlaySound_r(0, 4, m);
            }
            if ((d->travel = d->travel - step) < 0.0f) {
                if (d->sound != -1 && ((SoundSlot *)(hero_globals_base_r + 0x1D + d->sound * 0x70))->owner == m &&
                    ((SoundSlot *)(hero_globals_base_r + 0x1D + d->sound * 0x70))->active != 0) {
                    Sound_StopSlot(d->sound);
                }
                d->travel = 0;
                d->sound = -1;
                m->state = 1;
                if (d->key != -1) {
                    m->state = 5;
                    l15_key_gate_open_lui = 0;
                }
            }
            {
                float t = d->travel;
                float h = d->home.z;
                float z;
                if (d->key != -1) {
                    t = -t;
                    z = h + t;
                } else {
                    z = h + t;
                }
                m->pos.z = z;
            }
            if (is_point_inside_clip_volume(&((struct Hero *)((char *)&hero_globals_base_r + 0xE1D))->motion.pos,
                                            d->vol_near) != 0 ||
                is_point_inside_clip_volume(quartu_camera_pos_r, d->vol_near) != 0) {
                m->state = 2;
            }
            break;
        case 5:
            if (gemlik_available_r[3] != 0) {
                m->pos.z = d->home.z - D_L15_00161578_2A48B0;
                l15_key_gate_open_lui = 1;
            } else {
                if (hero_globals_base_r[0x2EC1] == 2) {
                    break;
                }
                m->pos.z = d->home.z;
                m->state = 1;
                l15_key_gate_open_lui = 0;
            }
            break;
    }
}

