/* Construction arm update (moby Construction Arm, level 15): a state machine on moby[0x20]. */
void construction_arm_update(char *moby) {
    enum {
        CONSTRUCTION_ARM_INITIALIZE = 0,
        CONSTRUCTION_ARM_WAIT_TO_TURN = 1,
        CONSTRUCTION_ARM_TURN_TO_TARGET_YAW = 2,
        CONSTRUCTION_ARM_WAIT_FOR_ENTRY_ANIMATION = 3,
        CONSTRUCTION_ARM_WAIT_TO_START_EXIT_ANIMATION = 4,
        CONSTRUCTION_ARM_WAIT_FOR_EXIT_ANIMATION = 5,
        CONSTRUCTION_ARM_DESTROY = 6
    };
    struct Moby *m = (struct Moby *)moby;
    UpdateVars_2938 *arm_vars = (UpdateVars_2938 *)m->pvars;
    int hit = 0;
    int t;
    struct HitMessage *slot;

    if (m->state != CONSTRUCTION_ARM_DESTROY) {
        slot = (struct HitMessage *)MobyGetHitMessage(m, 0x10000, 0);
        if (slot != 0 && 0.0f < slot->damage)
            hit = 1;
        if (hit)
            m->state = CONSTRUCTION_ARM_DESTROY;
    }
    if (m->state != CONSTRUCTION_ARM_INITIALIZE) {
        float g = g_frame_scale_sq;
        float v = arm_vars->yaw;
        float a = g * 0.03f;
        float b = g * 0.3f;
        arm_vars->facing = v;
        update_joint_animation(moby, arm_vars, 0, a, b);
    }
    switch (m->state) {
        case CONSTRUCTION_ARM_INITIALIZE: {
            float a = multiply_global_factor(construction_arm_wait_min * 60.0f);
            float b = multiply_global_factor(construction_arm_wait_max * 60.0f);
            int d = truncate_float_to_s32(random_float_between(a, b));
            arm_vars->timer = d;
            *(int *)&arm_vars->yaw = 0;
            arm_vars->side = 0;
            *(int *)&arm_vars->yaw_velocity = 0;
            m->update_dist = 0xFF;
            m->state = CONSTRUCTION_ARM_WAIT_TO_TURN;
            break;
        }
        case CONSTRUCTION_ARM_WAIT_TO_TURN: {
            int ok;
            int count;
            if (!FastDecTimer(&arm_vars->timer))
                break;
            if (!(fast_vec_dist(quartu_camera_pos, &m->pos) < 42.0f))
                break;
            {
                ok = 1;
                if (m->group != 0xFF) {
                    int lst = l15_moby_group_member_lists[m->group];
                    count = 0;
                    if (lst == 0)
                        break;
                    {
                        int base = quartu_moby_array;
                        unsigned short *list = (unsigned short *)lst;
                        for (;;) {
                            struct Moby *other;
                            int id;
                            t = *list;
                            id = t;
                            t &= 0x7FFF;
                            other = (struct Moby *)((t << 8) + base);
                            if ((signed char)other->state >= 0 && other->oclass == m->oclass && other->state != 1)
                                count++;
                            list++;
                            if ((id << 16) < 0)
                                break;
                        }
                    }
                    if (count != 0) {
                        arm_vars->timer = scale_ticks(0x3C);
                        ok = 0;
                    }
                }
            }
            if (!ok)
                break;
            arm_vars->target_yaw = random_float_between(-0.209439516f, 0.209439516f);
            m->state = CONSTRUCTION_ARM_TURN_TO_TARGET_YAW;
            break;
        }
        case CONSTRUCTION_ARM_TURN_TO_TARGET_YAW: {
            int r = random_int_between(0, 1);
            arm_vars->side = r;
            if (FastDiffRots(arm_vars->yaw, arm_vars->target_yaw) < 0.00872664619f) {
                int k = arm_vars->side * 2 + 1;
                int q = scale_ticks(6);
                MobyBlendAnimation(m, k, 0, q);
                m->state = CONSTRUCTION_ARM_WAIT_FOR_ENTRY_ANIMATION;
            }
            arm_vars->yaw =
                SpringTurn(&arm_vars->yaw_velocity, arm_vars->yaw, arm_vars->target_yaw, g_frame_time_sq * 1.57079637f,
                           g_frame_time_sq * 0.785398185f, g_frame_time * 0.785398185f);
            break;
        }
        case CONSTRUCTION_ARM_WAIT_FOR_ENTRY_ANIMATION: {
            if (m->prev_seq != arm_vars->side * 2 + 1)
                break;
            if (!(m->anim_flags & 2))
                break;
            arm_vars->timer = scale_ticks(random_int_between(0xF, 0x2D));
            {
                int k = arm_vars->side * 2 + 2;
                int q = scale_ticks(3);
                MobyBlendAnimation(m, k, 0, q);
            }
            arm_vars->direction = random_angle_radians();
            m->state = CONSTRUCTION_ARM_WAIT_TO_START_EXIT_ANIMATION;
            break;
        }
        case CONSTRUCTION_ARM_WAIT_TO_START_EXIT_ANIMATION: {
            if (fast_vec_dist(&m->pos, quartu_camera_pos) < 20.0f && random_integer_below(2) == 0 && m->visible != 0) {
                float A = construction_arm_puff_speed;
                float t1 = random_float_between(A / 5.0f, A);
                float f22 = t1 * g_frame_time;
                float t2 = random_float_between(0.0f, construction_arm_puff_speed / 5.0f);
                float f23 = t2 * g_frame_time;
                float t3 = random_angle_radians();
                float vP[4];
                float vA[4];
                float vB[4];
                float vO[4];
                float u1;
                float u2;
                float u3;
                float u4;
                u1 = FastCos(arm_vars->direction);
                vA[0] = u1 * f22;
                u2 = FastSin(arm_vars->direction);
                vA[1] = u2 * f22;
                vA[2] = 0.0f;
                u3 = FastCos(t3);
                vB[0] = u3 * f23;
                u4 = FastSin(t3);
                vB[1] = u4 * f23;
                vB[2] = 0.0f;
                add_vectors(vO, vA, vB);
                moby_point_position(m, 1, vP);
                {
                    int ra = scale_ticks(construction_arm_puff_life_min);
                    int rb = scale_ticks(construction_arm_puff_life_max);
                    int c = random_int_between(ra, rb);
                    spawn_burst(vP, vA, construction_arm_puff_color, construction_arm_puff_color, c, 1, 40000.0f);
                }
            }
            if (!FastDecTimer(&arm_vars->timer))
                break;
            {
                int k = arm_vars->side * 2 + 3;
                int q = scale_ticks(6);
                MobyBlendAnimation(m, k, 0, q);
            }
            m->state = CONSTRUCTION_ARM_WAIT_FOR_EXIT_ANIMATION;
            break;
        }
        case CONSTRUCTION_ARM_WAIT_FOR_EXIT_ANIMATION: {
            float a;
            float b;
            int r;
            if (m->prev_seq != arm_vars->side * 2 + 3)
                break;
            if (!(m->anim_flags & 2))
                break;
            a = multiply_global_factor(construction_arm_wait_min * 60.0f);
            b = multiply_global_factor(construction_arm_wait_max * 60.0f);
            t = truncate_float_to_s32(random_float_between(a, b));
            arm_vars->timer = t;
            r = scale_ticks(6);
            MobyBlendAnimation(m, 0, 0, r);
            m->state = CONSTRUCTION_ARM_WAIT_TO_TURN;
            break;
        }
        case CONSTRUCTION_ARM_DESTROY:
            Moby_PlaySound(0, 0, (int)m);
            cart_burst(m, &m->pos, -1, 1.5f, 13.0f);
            spawn_proximity_gated_bolts(m);
            SpawnBreakFragment(m, 0x74B, &m->pos, &m->rot, 0, 0, 0.0f, quartu_zero_vec, quartu_zero_vec,
                               quartu_zero_vec);
            SpawnBreakFragment(m, 0x74C, &m->pos, &m->rot, 0, 0, 0.0f, quartu_zero_vec, quartu_zero_vec,
                               quartu_zero_vec);
            SpawnBreakFragment(m, 0x74D, &m->pos, &m->rot, 0, 0, 0.0f, quartu_zero_vec, quartu_zero_vec,
                               quartu_zero_vec);
            DeleteMoby(m);
            break;
    }
}
