/* Steers a flying moby toward goal while facing look. */
void steer_helicopter(struct Moby *moby, Vec4 *goal, Vec4 *look) {
    Vec4 target;
    Vec4 look_copy;
    Vec4 scaled;
    Vec4 origin;
    Vec4 delta;
    Vec4 *look_at = &look_copy;
    Vec4 *target_at = &target;
    SteeringVars_4f88 *vars = (SteeringVars_4f88 *)moby->pvars;
    float distance;
    float step;
    float old_speed;
    float limit;
    float facing;
    float angle;
    float c;
    float s;
    float yaw_target;
    float pitch_target;
    float dx;
    float dy;
    float threshold;
    float speed_sq;
    float twice_step;
    float height;
    float pos_x;
    float pos_y;
#define frame_time D_0015EE6C
#define frame_time_sq D_0015EE70

    target.q = goal->q;
    look_copy.q = look->q;
    origin.q = *(SQuad *)&moby->pos;
    distance = fast_vec_dist(&moby->pos, target_at);
    step = frame_time_sq * 10.0f;
    old_speed = vars->speed;
    speed_sq = old_speed * old_speed;
    twice_step = step + step;
    threshold = speed_sq / twice_step;
    if (distance <= threshold) {
        vars->speed = old_speed - step;
        if (vars->speed < 0.0f) {
            vars->speed = 0.0f;
        }
    } else {
        vars->speed = old_speed + step;
        limit = frame_time * 10.0f;
        if (limit < vars->speed) {
            vars->speed = limit;
        }
    }

    FastVecSub(&delta, target_at, &moby->pos);
    scaled.q = delta.q;
    ((void (*)(float, void *, void *))vec_scale_to_length)(vars->speed * 0.1f, &scaled, &scaled);
    ((void (*)(float, void *, void *))FastVecScale)(0.9f, &delta, &vars->delta);
    vars->delta.q = delta.q;
    add_vectors(&delta, &vars->delta, &scaled);
    move_moby_with_sphere_collision(1.0f, 2.0f, moby, &vars->delta, 0);
    height = *(float *)&vars->height;
    pos_x = *(float *)&moby->pos.x;
    /* FAKEMATCH: volatile: this store stays before the next load (22/816 bytes differ without it). */
    *(volatile float *)&moby->pos.z = height;
    pos_y = *(float *)&moby->pos.y;
    /* FAKEMATCH: volatile: a nop stays, and so does the size (10/816 bytes differ without it). */
    dy = *(volatile float *)&look_at->f[1];
    /* FAKEMATCH: volatile: a nop stays, and so does the size (14/816 bytes differ without it). */
    dx = *(volatile float *)&look_at->f[0];
    dy = dy - pos_y;
    dx = dx - pos_x;
    facing = fast_atan2(dx, dy);
    moby->rot.z = SpringTurn(&vars->facing_velocity, moby->rot.z, facing, 0.01f, 0.3f, 0.1f);
    FastVecSub(&delta, &moby->pos, &origin);
    vars->delta.q = delta.q;
    angle = fast_atan2(vars->delta.f[0], vars->delta.f[1]);
    angle = FastSubRots(angle, moby->rot.z);
    c = FastCos(angle);
    yaw_target = (vars->speed * 0.34906584f * c) / (frame_time * 10.0f);
    s = FastSin(angle);
    pitch_target = (vars->speed * -0.34906584f * s) / (frame_time * 10.0f);
    moby->rot.y = SpringTurn(&vars->yaw_velocity, moby->rot.y, yaw_target, frame_time_sq * 0.5235988f,
                             frame_time_sq * 1.0471976f, frame_time * 0.7853982f);
    moby->rot.x = SpringTurn(&vars->pitch_velocity, moby->rot.x, pitch_target, frame_time_sq * 1.0471976f,
                             frame_time_sq * 2.0943952f, frame_time * 1.5707964f);
}
