/* Flocking step toward goal (cf. FUN_L15_002cf110): separates from live same-class mobys within 10 units and keeps ~15
   units off the goal while another moby is closer to it (~10 otherwise); writes the steering point to out and returns
   the heading to follow.
   Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l15/gameplay/entities/0029aff0.c, FUN_L15_002c52b8. */
float compute_helicopter_flocking_steering_point(struct Moby *m, float *out, Goal_52b8 goal) {
    float tmp[4];
    float dist;
    float wsum;
    int clear;
    float k;
    char *o;
    dist = vec_distance_xy(&m->pos, &goal);
    clear = 1;
    clear_u64_value(out);
    wsum = 0.0f;
    for (o = quartu_moby_list; o != 0; o = *(char **)(o + 0x28)) {
        if (o == m)
            continue;
        if (*(short *)(o + 0xA6) != m->oclass)
            continue;
        if ((u8)o[0x20] == 1 || (u8)o[0x20] == 0x40)
            continue;
        if (vec_distance_xy(o + 0x10, &m->pos) < 10.0f) {
            wsum += 6.0f;
            FastVecSub(tmp, &m->pos, o + 0x10);
            FastVecScale(tmp, tmp, 6.0f);
            FastVecAdd(out, out, tmp);
        }
        if (vec_distance_xy(o + 0x10, &goal) < dist)
            clear = 0;
    }
    if (clear == 0) {
        FastVecSub(tmp, &m->pos, &goal);
        if (dist < 14.5f) {
            k = 15.0f;
        } else if (15.5f < dist) {
            k = -15.0f;
        } else {
            k = 0.0f;
        }
        wsum += 10.0f;
        vec_scale_to_length(tmp, tmp, k * 10.0f);
        FastVecAdd(out, out, tmp);
        FastVecScale(out, out, 1.0f / wsum);
        FastVecAdd(out, out, &m->pos);
    } else {
        FastVecSub(tmp, &m->pos, &goal);
        if (dist < 9.5f) {
            k = 10.0f;
        } else if (10.5f < dist) {
            k = -10.0f;
        } else {
            k = 0.0f;
        }
        wsum += 10.0f;
        vec_scale_to_length(tmp, tmp, k * 10.0f);
        FastVecAdd(out, out, tmp);
        FastVecScale(out, out, 1.0f / wsum);
        FastVecAdd(out, out, &m->pos);
    }
    if (vec_distance_xy(&m->pos, out) < 1.0f) {
        qcopy(out, &m->pos);
        return fast_atan2(goal.pos.f[0] - m->pos.x, goal.pos.f[1] - m->pos.y);
    }
    return fast_atan2(out[0] - m->pos.x, out[1] - m->pos.y);
}
