/* Level 15 moby update: finds the table entry that owns this moby, runs its state switch and refreshes its range and
   target. */
void process_ultramech_hits_and_update_target(void *mobyp) {
    Moby *moby = (Moby *)((char *)mobyp);
    struct ProcessUltramechHitsAndUpdateTargetVars *data =
        (struct ProcessUltramechHitsAndUpdateTargetVars *)moby->pvars;
    char *other = 0;
    int i;
    Vec4A vA;
    Vec4A vB;
    int a40;
    int a44;
    float f48;
    int sel;
    int r2;

    moby->scale = ultramech_hit_check_scale * *(float *)(*(char **)&moby->pclass + 0x24);
    a44 = 0;
    data->unk_1C8 = 0;

    for (i = 0; i < 0x40; i++) {
        char *e = quartu_moby_hits + (i << 6);
        int fl;
        if (*(int *)(e + 0x34) != (int)moby)
            continue;
        fl = *(int *)(e + 0x24);
        if ((fl & 0xA0000) == 0)
            continue;
        if (*(int *)(e + 0x20) == *(int *)&g_hero.moby && (fl & 0x80000) == 0) {
            *(int *)(e + 0x34) = 0;
            continue;
        }
        other = e;
        break;
    }

    sel = ComputeHitResponse(moby, other, &data->unk_20, 0, &a40, &a44, 0, 4);
    if (other != 0 && a40 != 1 && (unsigned char)*(char *)&moby->state != 10 &&
        (unsigned char)*(char *)&moby->state != 0x40 && *(short *)(*(char **)(other + 0x20) + 0xA6) != 0x350) {
        float d;
        d = data->unk_20.f[0] - *(float *)&a44;
        data->unk_20.f[0] = d;
        if (*(unsigned short *)(other + 0x2A) == 0x100)
            sel = 9;
        if ((unsigned char)*(char *)&moby->state == 2)
            sel = 9;
        if (d <= 0.0f)
            sel = 1;

        r2 = truncate_float_to_s32(2560.0f);
        data->unk_80 = ultramech_knockback_gravity_gp * g_frame_time_sq;
        data->unk_90 = r2;
        data->unk_98 = 2.5f;
        data->unk_84 = 0.0005f;
        data->unk_94 = 9;
        data->unk_AD = 0;

        switch (sel) {
            case 0:
                break;
            case 9:
            case 10:
                data->unk_1C8 = 1;
                data->unk_67 = 0xFA;
                break;
            case 3:
            case 4:
            case 5:
            case 6:
            case 7:
            case 8: {
                char *p20;
                float k = g_frame_time;
                float a = ultramech_knockback_horizontal_speed_gp * k;
                float b = ultramech_knockback_vertical_speed_gp * k;
                float r;
                data->unk_1C8 = 1;
                data->unk_88 = a;
                data->unk_8C = b;
                trooper_set_knockback(&data->unk_70.f[0], 4.0f, 1.0f);
                data->unk_C0 = 12.0f;
                data->unk_C4 = 16.0f;
                p20 = *(char **)(other + 0x20);
                r = fast_atan2(moby->pos.x - *(float *)(p20 + 0x10), moby->pos.y - *(float *)(p20 + 0x14));
                *(u128 *)&vA = *(u128 *)(other + 0x10);
                f48 = r;
                trooper_knockback_arc(&vA, &f48, &data->unk_88, &data->unk_8C);
                InitKnockback_v(f48, moby, &data->unk_70, 8, 1, 0);
                Sound_PlayClassSound_r(0, 0, moby, 0x79);
                moby->state = 9;
                data->unk_67 = 0x78;
                break;
            }
            case 1:
            case 2:
                *(u128 *)&vA = 0;
                moby->flags &= 0xEFFF;
                moby_point_position(moby, 7, &vB);
                spawn_explosion(moby, &vA, &vB, 0.0f, 0.0f, 20, 6, 0x20, 16.0f, 8.0f, 9.0f, 4.0f, -1, 32.0f, 1, 0x10,
                                -1, 0);
                Sound_PlayClassSound_r(0, 0, moby, 0x79);
                moby->state = 10;
                data->unk_67 = 0xF0;
                SetDeathBits(moby, 0x200, -1);
                break;
            case 11:
                break;
        }
        RerollEffectCounter(moby, &data->unk_60);
    }
    if (other != 0)
        *(int *)(other + 0x34) = 0;

    moby->hit_slot = 0xFF;
    StepColorFade(moby, &data->unk_60);
    moby->scale = *(float *)(*(char **)&moby->pclass + 0x24) * ultramech_scale;
    data->unk_164 = 0;

    if ((unsigned char)*(char *)&moby->state == 1 || data->unk_1D0 == -1) {
        if ((unsigned char)*(char *)&moby->state == 1)
            data->unk_1B8 = data->unk_174;
        else
            data->unk_1B8 = data->unk_178;
        FindNearestTargetMoby_t(moby, &data->unk_120.f[0], data->unk_1B8);
    } else {
        UPath *p;
        data->unk_1B8 = data->unk_178;
        p = quartu_paths[data->unk_1D0];
        FindNearestEligibleMoby(data->unk_1B8, moby, &data->unk_120, 0, 0, p->pt, p->n);
    }

    if (data->unk_1B8 < fast_vec_dist(&moby->pos, &data->unk_120))
        data->unk_164 = 2;
    if (data->unk_160 == 0)
        data->unk_160 = *(int *)&g_hero.moby;
}
