/* Nudge a moby's field 0x48 toward a signed step depending on a linked moby's state. */
void linked_turning_moby_update(char *moby) {
    struct Moby *self = (struct Moby *)moby;
    int linked_moby_index = *(int *)self->pvars;
    if (linked_moby_index != -1) {
        struct Moby *other = (struct Moby *)(linked_moby_index * 256 + *(int *)&D_L15_00160058_g);
        struct LinkedYawSourceVars *linked_moby_vars = (struct LinkedYawSourceVars *)other->pvars;
        int linked_moby_state = other->state;
        float step;
        if (linked_moby_state == 2) {
            step = linked_state_yaw_rate_degrees_gp * 0.017453292f * g_frame_time;
            if (linked_moby_vars->reversed != 0)
                step = -step;
        } else if (linked_moby_state == 4) {
            step = linked_state_yaw_rate_degrees_gp * 0.017453292f * g_frame_time;
            if (linked_moby_vars->reversed == 0)
                step = -step;
        } else {
            return;
        }
        self->rot.z = FastAddRots(self->rot.z, step);
    }
}

/* Updates a moby: initialises its vector, then applies an angle-based offset. */
void SideDriftUpdate(char *moby) {
    enum { CONVEYOR_BELT_INITIALIZE = 0, CONVEYOR_BELT_UPDATE_FRAME_OFFSET = 3 };
    struct Moby *m = (struct Moby *)moby;
    struct SideDriftVars *data = (struct SideDriftVars *)m->pvars;
    if (((char *)data) != 0) {
        unsigned char state = m->state;
        switch (state) {
            case CONVEYOR_BELT_INITIALIZE: {
                char *frame_offset = (char *)&data->drift_x;
                clear_u64_value(frame_offset);
                data->flags |= 4;
                m->state = 3;
                break;
            }
            case CONVEYOR_BELT_UPDATE_FRAME_OFFSET:
                m->anim_speed = 1.3888889f;
                data->drift_x = FastCos(FastAddRots(m->rot.z, 1.5707964f)) * (g_frame_time * 2.5f);
                data->drift_y = FastSin(FastAddRots(m->rot.z, 1.5707964f)) * (g_frame_time * 2.5f);
                data->drift_z = 0;
                break;
        }
        update_entity_matrix(data->entity_matrix, &data->drift_x, &m->rot, &m->rot);
    }
}

