/* Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l15/gameplay/vendor/002e73c0.c, FUN_L15_002ebf28. */
void set_moby_list_visibility(int idx, int show) {
    short *p = (short *)l15_moby_group_member_lists[idx];
    if (p == 0)
        return;
    while (1) {
        struct Moby *moby = (struct Moby *)((unsigned char *)(quartu_moby_array_r2 + ((*p & 0x7FFF) << 8)));
        if (show) {
            moby->collision = *(int *)(*(char **)&moby->pclass + 0x10);
            moby->visible = 1;
            moby->flags &= 0xFFFC;
        } else {
            moby->collision = 0;
            moby->visible = 0;
            moby->flags |= 3;
        }
        if (*p++ < 0)
            return;
    }
}
/* Counts the mobys in group idx that are dead or missing. */
int count_missing_or_dying_mobys_in_list(int idx) {
    unsigned short *p = (unsigned short *)l15_moby_group_member_lists[idx];
    int n = 0;
    int base;
    if (p == 0)
        return 0;
    base = quartu_moby_array;
    do {
        unsigned char *moby = (unsigned char *)(base + ((p[0] & 0x7FFF) << 8));
        if (moby == 0 || moby[0x20] == 0xFE || moby[0x20] == 0xFD)
            n++;
    } while ((short)*p++ >= 0);
    return n;
}
